-- Imagens de referência ENEM 2021 PPL/Reaplicação.
-- Data URI PNG, compatível com o editor e a exportação DOCX.
DO $migration$
DECLARE changed_rows integer;
BEGIN
  WITH image_map(id, image_url) AS (VALUES
    ('4a24bbef-8b8f-5d6f-9b0a-eedaf81487d7'::uuid, 'data:image/png;base64,'),
    ('77805574-3147-5301-8dbc-86164a1217b3'::uuid, 'data:image/png;base64,'),
    ('2c5d4467-05ed-5d1f-969c-c315589f16f1'::uuid, 'data:image/png;base64,'),
    ('31b006ff-f02c-51ed-b653-637fa388e996'::uuid, 'data:image/png;base64,'),
    ('d895655f-b3d5-5cab-b9c5-5c2ec01b9973'::uuid, 'data:image/png;base64,'),
    ('50b2e8b5-4fba-5076-a0c5-5d6ee2a6481f'::uuid, 'data:image/png;base64,'),
    ('1dafa039-32de-5ccc-9050-cfd38c399e96'::uuid, 'data:image/png;base64,'),
    ('3b74b2b6-c7ff-561e-9da3-1893db6943fb'::uuid, 'data:image/png;base64,'),
    ('7c13426c-fb58-5d96-9d46-b164f5f68342'::uuid, 'data:image/png;base64,'),
    ('cc7f9127-9e3b-5c39-a583-5e4456f4aec6'::uuid, 'data:image/png;base64,')
  )
  UPDATE public.questions AS q
  SET referencia_imagens_extra = jsonb_set(
        q.referencia_imagens_extra,
        '{0}',
        (q.referencia_imagens_extra->0 - 'pending') || jsonb_build_object('url', image_map.image_url),
        true
      ),
      tem_imagem = true,
      updated_at = now()
  FROM image_map
  WHERE q.id = image_map.id
    AND q.ano = '2021'
    AND q.prova = 'ENEM'
    AND jsonb_typeof(q.referencia_imagens_extra) = 'array'
    AND jsonb_array_length(q.referencia_imagens_extra) > 0;

  GET DIAGNOSTICS changed_rows = ROW_COUNT;
  IF changed_rows <> 10 THEN
    RAISE EXCEPTION 'ENEM 2021 reference import expected 10 rows, updated %', changed_rows;
  END IF;
END
$migration$;
